create or replace function public.pantavion_hydrate_social_post_media() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare m public.personal_media%rowtype; begin if new.personal_media_id is null then if new.storage_path is null then raise exception 'social media attachment requires personal_media_id or storage_path'; end if; return new; end if; select * into m from public.personal_media where id=new.personal_media_id; if not found then raise exception 'personal media item not found'; end if; if m.owner_id<>new.owner_id then raise exception 'personal media owner mismatch'; end if; new.storage_path:=m.storage_path; new.mime_type:=m.mime_type; new.media_kind:=case when m.media_kind='photo' then 'photo' when m.media_kind='video' then 'video' when m.media_kind='audio' then 'audio' else 'file' end; return new; end $$; revoke all on function public.pantavion_hydrate_social_post_media() from public,anon,authenticated; drop trigger if exists social_post_media_hydrate on public.social_post_media; create trigger social_post_media_hydrate before insert or update of personal_media_id,owner_id on public.social_post_media for each row execute function public.pantavion_hydrate_social_post_media();